\end{aligned}
\tag{P}\label{P:baseproblemIntro}

nodes.statement:
Consider the gradient algorithm with constant step size, as applied to problem $(M)$, which generates a sequence of
points as follows:\medskip

\fbox{\parbox{14cm}{ {\bf Algorithm GM} \medskip
\begin{enumerate}
\setcounter{enumi}{-1}
\item Input: $f\in C^{1,1}_L(\mathbb{R}^d)$ convex, $x_0\in \mathbb{R}^d.$
\item For $i=0,\dots,N-1$, compute $x_{i+1} = x_i - \frac{h}{L} f^\prime(x_i)$.
\end{enumerate}
}}
\bigskip

Here $h>0$ is fixed.

Let $f:\mathbb{R}^d \to \mathbb{R}$ be convex and $C^{1,1}_L$. Then,
\begin{equation} \frac{1}{2L} \|f^\prime(x)-f^\prime(y)\|^2 \leq f(x)-f(y)-\langle f^\prime(y), x-y\rangle, \;\mbox{for all}
    \; x,y\in \mathbb{R}^d.
\end{equation}

conclusions:
\label{E:basicconvexprop}
    \frac{1}{2L} \|f^\prime(x)-f^\prime(y)\|^2 \leq f(x)-f(y)-\langle f^\prime(y), x-y\rangle, \;\mbox{for all}
    \; x,y\in \mathbb{R}^d.

nodes.statement:
Now define
\begin{align*}
    \delta_i &:= \frac{1}{L\|x_\ast-x_0\|^2}(f(x_i)-f(x_\ast)),\quad i=0,\dots,N, \ast \\
    g_i &:= \frac{1}{L\|x_\ast-x_0\|}f^\prime(x_i),\quad i=0,\dots,N, \ast
\end{align*}
and note that  we always have $\delta_\ast=0$ and $g_\ast=0$.

After some algebra, we reach the following form for the PEP:
\begin{align*}
    \begin{aligned}
    \max_{x_0,x_\ast,g_i \in\mathbb{R}^d,\delta_i \in\mathbb{R}}\ & L\|x_\ast-x_0\|^2 \delta_N \\
    \text{s.t. }
                        & \frac{1}{2} \| g_i - g_j \| ^2 \leq \delta_i - \delta_j - \langle g_j, \sum_{t=i+1}^{j} h g_{t-1} \rangle,\quad i<j=0,\dots,N, \\
                        & \frac{1}{2} \| g_i - g_j \| ^2 \leq \delta_i - \delta_j + \langle g_j, \sum_{t=j+1}^{i} h g_{t-1} \rangle,\quad j<i=0,\dots,N, \\
                        & \frac{1}{2} \| g_i \| ^2 \leq \delta_i,\quad                                                                                          i=0,\dots,N, \\
                        & \frac{1}{2} \| g_i \| ^2 \leq - \delta_i - \langle g_i, \nu + \sum_{t=1}^{i} h g_{t-1} \rangle,\quad  i=0,\dots,N, \\
                        & \|x_\ast-x_0\| \leq R,
    \end{aligned}
\end{align*}
where $i<j=0,\dots,N$ is a shorthand notation  for $i=0,\dots,N-1, j= i+1,\dots, N$.

This
produces the following PEP for the gradient method, a {\em nonconvex quadratic} minimization
problem:
\begin{align*}
    \begin{aligned}
    \max_{g_i \in\mathbb{R}^d,\delta_i \in\mathbb{R}}\ & LR^2 \delta_N \\
    \text{s.t. }
                        & \frac{1}{2} \| g_i - g_j \| ^2 \leq \delta_i - \delta_j - \langle g_j, \sum_{t=i+1}^{j} h g_{t-1} \rangle,\quad i<j=0,\dots,N, \\
                        & \frac{1}{2} \| g_i - g_j \| ^2 \leq \delta_i - \delta_j + \langle g_j, \sum_{t=j+1}^{i} h g_{t-1} \rangle,\quad j<i=0,\dots,N, \\
                        & \frac{1}{2} \| g_i \| ^2 \leq \delta_i,\quad                                                                                                  i=0,\dots,N, \\
                        & \frac{1}{2} \| g_i \| ^2 \leq - \delta_i - \langle g_i, \nu + \sum_{t=1}^{i} h g_{t-1} \rangle,\quad  i=0,\dots,N. \\
    \end{aligned}
\end{align*}

\begin{aligned}
    A_{i,j} &= \frac{1}{2} (u_i-u_j)(u_i-u_j)^T + \frac{1}{2}\sum_{t=i+1}^{j} h (u_j u_{t-1}^T+u_{t-1} u_j^T),\\
    B_{i,j} &= \frac{1}{2} (u_i-u_j)(u_i-u_j)^T -  \frac{1}{2}\sum_{t=j+1}^{i} h (u_j u_{t-1}^T+u_{t-1} u_j^T),\\
    C_i &= \frac{1}{2} u_i u_i^T,\\
    D_i &= \frac{1}{2} u_i u_i^T+ \frac{1}{2}\sum_{t=1}^{i} h (u_i u_{t-1}^T + u_{t-1} u_i^T),
\end{aligned}

\begin{aligned}
    \max_{G\in \mathbb{R}^{(N+1)\times d},\delta \in\mathbb{R}^{N+1}}\ &  LR^2 \delta_N \\
    \text{s.t. }
                        & \mathrm{tr} (G^T A_{i,j} G) \leq \delta_i - \delta_j,\quad    i<j=0,\dots,N, \\
                        & \mathrm{tr}(G^T B_{i,j} G) \leq \delta_i - \delta_j,\quad      j<i=0,\dots,N, \\
                        & \mathrm{tr}(G^T C_i G) \leq \delta_i,\quad                             i=0,\dots,N, \\
                        & \mathrm{tr}(G^T D_i G+ \nu u_i^T G ) \leq - \delta_i,\quad     i=0,\dots,N.
    \end{aligned}
    \tag{G}

\begin{aligned}
    \max_{G\in \mathbb{R}^{(N+1)\times d},\delta \in\mathbb{R}^{N+1}}\ &  LR^2 \delta_N \\
    \text{s.t. }
                        & \mathrm{tr} (G^T A_{i-1,i} G) \leq \delta_{i-1} - \delta_i,\quad    i=1,\dots,N, \\
                        & \mathrm{tr}(G^T D_i G+ \nu u_i^T G ) \leq - \delta_i,\quad     i=0,\dots,N.
    \end{aligned}
    \tag{G$^\prime$}

Consider problem \eqref{P:gpr} for any fixed $h\in \mathbb{R}$ and  $L,R >0$.
A Lagrangian dual of \eqref{P:gpr} is given by the following convex program:
\begin{align*}
    \begin{aligned}
        \min_{\lambda \in \mathbb{R}^N, t \in \mathbb{R}}\{\frac{1}{2} LR^2 t:\; \lambda \in \Lambda, \; S(\lambda, t) \succeq 0 \},
    \end{aligned}
    \tag{DG$^\prime$} \end{align*}
where $\Lambda:=\{\lambda \in \mathbb{R}^N:\; \lambda_{i+1}-\lambda_i \geq 0, \quad
i=1,\dots,N-1,\; 1-\lambda_N \geq 0,\; \lambda_i \geq 0,\quad i=1,\dots,N\}$,
the matrix
$S(\cdot,\cdot)\in \mathbb{S}^{N+2}$ is given by \[
    S(\lambda,t)=\begin{pmatrix}
                (1-h)S_0 + h S_1    & q \\
                q^T     & t
        \end{pmatrix},
\]
with $q=(\lambda_1,\lambda_2-\lambda_1,\dots,\lambda_N-\lambda_{N-1},1-\lambda_N)^T$ and where
the matrices $S_0, S_1\in \mathbb{S}^{N+1}$ are  defined by: {\small
\begin{equation} S_0=
    \begin{pmatrix}
        2 \lambda_1     & -\lambda_1            \\
        -\lambda_1          & 2 \lambda_2   & -\lambda_2                \\
            &       -\lambda_2          & 2 \lambda_3   & -\lambda_3                \\
                                    &        & \ddots        &\ddots &   \ddots\\
                                            & &                 &       -\lambda_{N-1}  & 2 \lambda_N & -\lambda_N \\
                                            & &                 &        &  -\lambda_N  & 1\\
    \end{pmatrix}
\end{equation}
}
 and
{\small {\begin{equation} S_1=
        \begin{pmatrix}
        2 \lambda_1         & \lambda_2-\lambda_1           &\dots          &\lambda_N-\lambda_{N-1}    &1-\lambda_N  \\
        \lambda_2-\lambda_1         & 2 \lambda_2                   &           &\lambda_N-\lambda_{N-1}    &1-\lambda_N \\

        \vdots & & \ddots & &\vdots \\
        \lambda_N-\lambda_{N-1}     & \lambda_N-\lambda_{N-1}   &       & 2\lambda_N    & 1-\lambda_N  \\
        1-\lambda_N         & 1-\lambda_N       & \dots         & 1-\lambda_N   & 1 \\
    \end{pmatrix}
    .
\end{equation}}}

\begin{aligned}
        \min_{\lambda \in \mathbb{R}^N, t \in \mathbb{R}}\{\frac{1}{2} LR^2 t:\; \lambda \in \Lambda, \; S(\lambda, t) \succeq 0 \},
    \end{aligned}
    \tag{DG$^\prime$}

\begin{aligned}
    \min_{G\in \mathbb{R}^{(N+1)\times d},\delta \in\mathbb{R}^{N+1}}\ &  -\delta_N \\
    \text{s.t. }
                        & \mathrm{tr} (G^T A_{i-1,i} G) \leq \delta_{i-1} - \delta_i,\quad    i=1,\dots,N, \\
                        & \mathrm{tr}(G^T D_i G+ \nu u_i^T G ) \leq - \delta_i,\quad     i=0,\dots,N.
    \end{aligned}
    \tag{G$^{\prime\prime}$}

\begin{aligned}
        \max \{ H(\lambda, \tau):\; \lambda \in\mathbb{R}^{N}_{+}, \tau \in \mathbb{R}^{N+1}_{+}\}.
    \end{aligned}
    \tag{DG$^{\prime\prime}$}

Let
\begin{align*}
    \lambda_i &= \frac{i}{2 N+1-i},\qquad i=1,\dots,N,
\end{align*}
then the matrices $S_0, S_1 \in \mathbb{S}^{N+1}$ defined in (\ref{b0matrix})--(\ref{b1matrix})
are positive definite for every $N\in\mathbb{N}$.

Consider the following class of first-order methods:
\medskip

\fbox{\parbox{14cm}{ {\bf Algorithm FO} \medskip
\begin{enumerate}
\setcounter{enumi}{-1}
\item Input: $f\in C^{1,1}_L(\mathbb{R}^d)$, $x_0\in \mathbb{R}^d.$
\item For $i=0,\dots,N-1$, compute $x_{i+1} = x_i - \frac{1}{L} \sum_{k=0}^{i} h^{(i+1)}_{k} f^\prime(x_k)$.
\end{enumerate}
}}
\medskip

Here, $h_k^{(i)} \in \mathbb{R}$ play the role of step-sizes, which we assume to be fixed and determined by
the algorithm.

\textbf{The Heavy Ball Method (HBM)}

\fbox{\parbox{14cm}{ {\bf Algorithm HBM} \medskip
\begin{enumerate}
\setcounter{enumi}{-1}

\item Input: $f\in C^{1,1}_L(\mathbb{R}^d)$, $x_0\in \mathbb{R}^d$,
\item $x_1 \leftarrow x_0 - \frac{\alpha}{L} f^\prime(x_0)$
\item For $i=1,\dots,N-1$ compute: $x_{i+1} = x_i - \frac{\alpha}{L} f^\prime(x_i) +\beta (x_i-x_{i-1})$ \end{enumerate}
}}
\medskip

Here the step sizes $\alpha$ and  $\beta$ are chosen such that $0 \leq \beta < 1$ and $0 < \alpha <
2(1+\beta)$, see \cite{polyak1964}.

By recursively eliminating the term $x_i-x_{i-1}$ in step 2 of HBM, we can rewrite this step
as
\[
    x_{i+1}= x_i - \frac{1}{L} \sum_{k=0}^{i} \alpha \beta^{i-k} f^\prime(x_k),\quad i=1,\dots,N-1.
\]
Therefore, the heavy ball method is a special case of Algorithm~\text{FO}\xspace with the choice
$$h^{(i+1)}_{k}= \alpha \beta^{i-k}, \quad  k=0, \ldots, i, \; i=0, \ldots N-1 .$$

\textbf{The Heavy Ball Method (HBM)}

\fbox{\parbox{14cm}{ {\bf Algorithm HBM} \medskip
\begin{enumerate}
\setcounter{enumi}{-1}

\item Input: $f\in C^{1,1}_L(\mathbb{R}^d)$, $x_0\in \mathbb{R}^d$,
\item $x_1 \leftarrow x_0 - \frac{\alpha}{L} f^\prime(x_0)$
\item For $i=1,\dots,N-1$ compute: $x_{i+1} = x_i - \frac{\alpha}{L} f^\prime(x_i) +\beta (x_i-x_{i-1})$ \end{enumerate}
}}
\medskip

Here the step sizes $\alpha$ and  $\beta$ are chosen such that $0 \leq \beta < 1$ and $0 < \alpha <
2(1+\beta)$, see \cite{polyak1964}.

\textbf{The fast gradient method (FGM)}

\fbox{\parbox{14cm}{ {\bf Algorithm FGM} \medskip
\begin{enumerate}
\setcounter{enumi}{-1}

\item Input: $f\in C^{1,1}_L(\mathbb{R}^d)$, $x_0\in \mathbb{R}^d$,
\item $y_1 \leftarrow x_0$, $t_1 \leftarrow 1$,
\item For $i=1,\dots,N$ compute:
\begin{enumerate}
    \item $x_i \leftarrow y_i -\frac{1}{L} f^\prime(y_i)$, \item $t_{i+1} \leftarrow \frac{1+\sqrt{1+4 t_i^2}}{2}$,
    \item $y_{i+1} \leftarrow x_i + \frac{t_i-1}{t_{i+1}}(x_i-x_{i-1})$. \end{enumerate}
\end{enumerate}
}}

For $i=1,\dots,N$ compute:
\begin{enumerate}
    \item $x_i \leftarrow y_i -\frac{1}{L} f^\prime(y_i)$, \item $t_{i+1} \leftarrow \frac{1+\sqrt{1+4 t_i^2}}{2}$,
    \item $y_{i+1} \leftarrow x_i + \frac{t_i-1}{t_{i+1}}(x_i-x_{i-1})$. \end{enumerate}

Observing that the gradient of the function is only evaluated on the {\em auxiliary sequence}
of points $\{y_i\}$, we show in the next proposition that

FGM fits in the scheme \text{FO}\xspace through the following algorithm:

\fbox{\parbox{14cm}{ {\bf Algorithm \text{FGM$^\prime$}\xspace} \medskip
\begin{enumerate}
\setcounter{enumi}{-1}
\item Input: $f\in C^{1,1}_L(\mathbb{R}^d)$, $x_0\in \mathbb{R}^d$,
\item $y_1 \leftarrow x_0$,
\item For $i=1,\dots,N-1$ compute:
\begin{enumerate}
    \item$y_{i+1} \leftarrow y_i  -\frac{1}{L} \sum_{k=1}^{i} h^{(i+1)}_{k} f^\prime(y_k)$, \end{enumerate}
\item $x_N \leftarrow y_N -\frac{1}{L} f^\prime(y_N)$,
\end{enumerate}
}}

with
\begin{align}
    h^{(i+1)}_k = \begin{cases}
        \frac{t_{i}-1}{t_{i+1}}h^{(i)}_k    & k+2\leq i, \\
        \frac{t_{i}-1}{t_{i+1}}(h^{(i)}_{i-1}-1)    & k = i-1, \\
        1+\frac{t_{i}-1}{t_{i+1}}   & k = i
    \end{cases} \qquad (i=1,\dots,N-1, \ k=1,\dots,i). \end{align}
and
\begin{align*}
    t_i =
        \begin{cases}
            1       & i=1 \\
            \frac{1+\sqrt{1+4 t_{i-1}^2}}{2} & i>1.
        \end{cases}
\end{align*}

\begin{aligned}
    \max_{G\in \mathbb{R}^{(N+1)\times d},\delta_i \in\mathbb{R}}\ &  LR^2 \delta_N \\
    \text{s.t. }
                        & \mathrm{tr} (G^T \tilde{A}_{i,j} G) \leq \delta_i - \delta_j,\quad    i<j=0,\dots,N, \\
                        & \mathrm{tr}(G^T \tilde{B}_{i,j} G) \leq \delta_i - \delta_j,\quad      j<i=0,\dots,N, \\
                        & \mathrm{tr}(G^T \tilde{C}_i G) \leq \delta_i,\quad                             i=0,\dots,N, \\
                        & \mathrm{tr}(G^T \tilde{D}_i G+ \nu u_i^T G ) \leq - \delta_i,\quad     i=0,\dots,N,
    \end{aligned}
    \tag{Q}

\begin{aligned}
    \tilde{A}_{i,j} &= \frac{1}{2} (u_i-u_j)(u_i-u_j)^T + \frac{1}{2}\sum_{t=i+1}^{j} \sum_{k=0}^{t-1} h_k^{(t)}(u_j u_k^T+u_k u_j^T),\\
    \tilde{B}_{i,j} &= \frac{1}{2} (u_i-u_j)(u_i-u_j)^T -  \frac{1}{2}\sum_{t=j+1}^{i} \sum_{k=0}^{t-1} h_k^{(t)}(u_j u_k^T+u_k u_j^T),\\
    \tilde{C}_i &= \frac{1}{2} u_i u_i^T,\\
    \tilde{D}_i &= \frac{1}{2} u_i u_i^T+  \frac{1}{2}\sum_{t=1}^{i} \sum_{k=0}^{t-1} h_k^{(t)} (u_i u_k^T + u_k u_i^T)
\end{aligned}

\begin{aligned}
    \max_{G\in \mathbb{R}^{(N+1)\times d},\delta_i \in\mathbb{R}}\ &  LR^2 \delta_N \\
    \text{s.t. }
                        & \mathrm{tr} (G^T \tilde{A}_{i-1,i} G) \leq \delta_{i-1} - \delta_i,\quad    i=1,\dots,N, \\
                        & \mathrm{tr}(G^T \tilde{D}_i G+ \nu u_i^T G ) \leq - \delta_i,\quad     i=0,\dots,N.
    \end{aligned}
    \tag{Q$^\prime$}

With the same proof as given in Lemma~\ref{lem:dual}  for problem \eqref{P:fopr}, we obtain that a dual
problem for \eqref{P:fopr} is given by the following convex semidefinite optimization problem:


\begin{align*}
    \begin{aligned}
    \min_{\lambda, \tau,t}\ & \frac{1}{2} t \\
    \text{s.t. }
            & \begin{pmatrix}
                \sum_{i=1}^N \lambda_i  \tilde{A}_{i-1,i}  + \sum_{i=0}^N \tau_i  \tilde{D}_i  &\frac{1}{2} \tau \\
                \frac{1}{2} \tau^T      & \frac{1}{2} t
        \end{pmatrix} \succeq 0, \\
        & (\lambda, \tau) \in \tilde{\Lambda},
    \end{aligned}
    \tag{DQ$^\prime$} \end{align*}
where
\begin{equation} \tilde{\Lambda} = \{ (\lambda,\tau) \in \mathbb{R}^{N}_{+}\times \mathbb{R}^{N+1}_{+} :
         \tau_0 = \lambda_1, \
        \lambda_i-\lambda_{i+1}+\tau_i = 0, \  i=1,\dots,N-1,\
        \lambda_N+\tau_N=1
    \}.
\end{equation}

\begin{aligned}
    \min_{\lambda, \tau,t}\ & \frac{1}{2} t \\
    \text{s.t. }
            & \begin{pmatrix}
                \sum_{i=1}^N \lambda_i  \tilde{A}_{i-1,i}  + \sum_{i=0}^N \tau_i  \tilde{D}_i  &\frac{1}{2} \tau \\
                \frac{1}{2} \tau^T      & \frac{1}{2} t
        \end{pmatrix} \succeq 0, \\
        & (\lambda, \tau) \in \tilde{\Lambda},
    \end{aligned}
    \tag{DQ$^\prime$}

conclusions:
the numerical bounds for the main sequence of point $x_i$ and the corresponding
values at the auxiliary sequence $y_i$ of the fast gradient method are very similar and
perform slightly better than predicted by the classical bound \eqref{E:nesterovBound}

