Substituting \eqref{E:mkdet} in the RHS of \eqref{E:mrecursion} we get that for $k=2,\dots,N$
\begin{align*}
     & \alpha_k \det M_{k-1} - \beta_k \det M_{k-2}\\
        &= \alpha_k f_{k-1} \left(1+g_{k-1}\sum_{i=0}^{k-1} x_i\right) \prod_{i=0}^{k-1} y_i - \beta_k f_{k-2}\left(1+g_{k-2}\sum_{i=0}^{k-2} x_i \right) \prod_{i=0}^{k-2} y_i\\

        &= \left( \alpha_k f_{k-1} \left(1+g_{k-1} x_{k-1}+g_{k-1}\sum_{i=0}^{k-2} x_i\right)-\frac{\beta_k}{y_{k-1}} f_{k-2}-\frac{\beta_k}{y_{k-1}} f_{k-2} g_{k-2}\sum_{i=0}^{k-2} x_i \right) \prod_{i=0}^{k-1} y_i\\
        &= \left( \alpha_k f_{k-1}(1+ g_{k-1} x_{k-1}) -\frac{\beta_k}{y_{k-1}} f_{k-2}+\left( \alpha_k f_{k-1} g_{k-1}-\frac{\beta_k}{y_{k-1}} f_{k-2} g_{k-2}\right) \sum_{i=0}^{k-2} x_i\right) \prod_{i=0}^{k-1} y_i.
\end{align*}
It is straightforward (although somewhat involved) to verify that for $k<N$
\begin{align*}
    & \alpha_k f_{k-1} (1+ g_{k-1} x_{k-1}) -\frac{\beta_k}{y_{k-1}} f_{k-2} = f_k y_k (1+g_k x_{k-1}+g_k x_k),
\end{align*}
and
\begin{align*}
    & \alpha_k f_{k-1}g_{k-1}-\frac{\beta_k}{y_{k-1}} f_{k-2} g_{k-2} = f_k g_k y_k.
\end{align*}
We therefore get
\begin{align*}
    & \alpha_k \det M_{k-1} -\beta_k \det M_{k-2} \\
    & = \left( f_k y_k(1+g_k x_{k-1}+g_k x_k)+ f_k g_k y_k \sum_{i=0}^{k-2} x_i\right) \prod_{i=0}^{k-1} y_i\\

    & = f_k \left( 1+g_k \sum_{i=0}^{k} x_i\right) \prod_{i=0}^{k} y_i\\
    & = \det M_k,
\end{align*}
and thus \eqref{E:mkdet} satisfies \eqref{E:mrecursion}. It is also possible to show that
\begin{align*}
    & \alpha_N f_{N-1}(1+ g_{N-1} x_{N-1}) -\frac{\beta_N}{y_{N-1}} f_{N-2} = \frac{(2N+1)^2}{(N+1)^2}, \\
    & \alpha_N f_{N-1} g_{N-1}-\frac{\beta_N}{y_{N-1}} f_{N-2} g_{N-2} = 0,
\end{align*}
thus, for $k=N$
\begin{align*}
    & \alpha_N \det M_{N-1} -\beta_N \det M_{N-2} \\
    & = \frac{(2N+1)^2}{(N+1)^2} \prod_{i=0}^{N-1} y_i  \\
    & = \det M_N,
\end{align*}
and the expression \eqref{E:mndet} is also verified.




To complete the proof, note that the closed form expressions for $\det M_k$ consist of sums
and products of positive values, hence $\det M_k$ is positive, and thus follows from
Sylvester's criterion that $S_1$ is positive definite.

\paragraph{Closed form expressions for the determinants}
Going back to our matrix, $S_1$, by choosing
\begin{align*}
    & d_i = 2\frac{i+1}{2 N-i},\quad i=0,\dots,N-1 \\
    & d_N = 1 \\
    & a_i = \frac{i+1}{2 N-i}-\frac{i}{2 N+1-i},\quad i=1,\dots,N-1\\
    & a_N = 1-\frac{N}{N+1} = \frac{1}{N+1},
\end{align*}
we get that $M_k$ is the $k+1$'th leading principal minor of the matrix $S_1$.
The recursion rule~\eqref{E:mrecursion} can now be solved for this choice of $a_i$ and $d_i$. The solution is given by:
\begin{align}
    \det M_k =& \frac{(2N+1)^2}{(2N-k)^2} \left( 1 +\sum_{i=0}^k \frac{2N-2k-1}{2N+4 N i - 2 i^2+1}\right) \prod_{i=0}^{k} \frac{2N+4Ni-2i^2+1}{(2N+1-i)^2}, \end{align}
for $k=0,\dots,N-1$, and
\begin{align}
    \det M_N = \det L_1
        =& \frac{(2N+1)^2}{(N+1)^2}\prod_{i=0}^{N-1} \frac{2N+4Ni-2i^2+1}{(2N+1-i)^2} .
\end{align}

\paragraph{Verification}
We now proceed to verify the expressions \eqref{E:mkdet} and \eqref{E:mndet} given above. We will show that these expressions satisfy the recursion rule \eqref{E:mrecursion}
and the base cases of the problem. We begin by verifying the base cases:
\begin{align*}
    \det M_0 & = \frac{(2N+1)^2}{(2N)^2}\left( 1 +\frac{2N-1}{2N+1}\right) \frac{1}{2N+1}= \frac{1}{N} = d_0,
\end{align*}
\begin{align*}
    \det M_1 & = \frac{(2N+1)^2}{(2N-1)^2} \left( 1 +\frac{2N-3}{2N+1}+ \frac{2N-3}{6N -1}\right) \frac{1}{2N+1} \frac{6N-1}{(2N)^2}  \\
        &= \frac{28N^2-20N-1}{4N^2(2N-1)^2} = \frac{4}{N(2N-1)}-\left(\frac{2}{2N-1}-\frac{1}{2N}\right)^2= d_0 d_1-a_1^2.
\end{align*}
Now suppose $2 \leq k\leq N$. Denote
\begin{align*}
    \alpha_k
            &= d_k-\frac{2 a_k^2}{a_{k-1}}+\frac{a_k^2 d_{k-1}}{a_{k-1}^2} \\
            &=\begin{cases}
                4\frac{(2N+1)k-k^2-1}{(2N-k)^2},            &k<N\\
                3\frac{2N^2+2N-1}{(2N+1)^2},    &k=N
            \end{cases} \\
    \beta_k &= a_k^2\left(1-\frac{d_{k-1}}{a_{k-1}}\right)^2 \\
                &=\begin{cases}
                    \frac{(4 kN-2N-2k^2+4k-1)^2}{(2N-k)^2(2N-k+1)^2}, &k<N\\
                    \frac{(2N^2+2N-1)^2}{(N+1)^2(2N+1)^2}, &k=N
                \end{cases},
\end{align*}
then the recursion rule \eqref{E:mrecursion} can be written as
\begin{align*}
    & \det M_k= \alpha_k \det M_{k-1} - \beta_k \det M_{k-2}.
\end{align*}
Further denote
\begin{align*}
    f_i &= \frac{(2N+1)^2}{(2N-i)^2}, \quad i=0,\dots,N-1, \\
    g_i &= 2N-2i-1, \quad i=0,\dots,N-1,\\
    x_i &= \frac{1}{2N+4 N i - 2 i^2+1}, \quad i=0,\dots,N-1, \\
    y_i &= \frac{2N+4Ni-2i^2+1}{(2N+1-i)^2}, \quad i=0,\dots,N-1,
\end{align*}
then the solution \eqref{E:mkdet} becomes
\begin{align*}
    \det M_k =& f_k \left(1+g_k \sum_{i=0}^{k} x_i\right) \prod_{i=0}^{k} y_i,
\end{align*}
and \eqref{E:mndet} becomes
\begin{align*}
    \det M_N =& \frac{(2N+1)^2}{(N+1)^2} \prod_{i=0}^{N-1} y_i.
\end{align*}

Substituting \eqref{E:mkdet} in the RHS of \eqref{E:mrecursion} we get that for $k=2,\dots,N$
\begin{align*}
     & \alpha_k \det M_{k-1} - \beta_k \det M_{k-2}\\
        &= \alpha_k f_{k-1} \left(1+g_{k-1}\sum_{i=0}^{k-1} x_i\right) \prod_{i=0}^{k-1} y_i - \beta_k f_{k-2}\left(1+g_{k-2}\sum_{i=0}^{k-2} x_i \right) \prod_{i=0}^{k-2} y_i\\

        &= \left( \alpha_k f_{k-1} \left(1+g_{k-1} x_{k-1}+g_{k-1}\sum_{i=0}^{k-2} x_i\right)-\frac{\beta_k}{y_{k-1}} f_{k-2}-\frac{\beta_k}{y_{k-1}} f_{k-2} g_{k-2}\sum_{i=0}^{k-2} x_i \right) \prod_{i=0}^{k-1} y_i\\
        &= \left( \alpha_k f_{k-1}(1+ g_{k-1} x_{k-1}) -\frac{\beta_k}{y_{k-1}} f_{k-2}+\left( \alpha_k f_{k-1} g_{k-1}-\frac{\beta_k}{y_{k-1}} f_{k-2} g_{k-2}\right) \sum_{i=0}^{k-2} x_i\right) \prod_{i=0}^{k-1} y_i.
\end{align*}
It is straightforward (although somewhat involved) to verify that for $k<N$
\begin{align*}
    & \alpha_k f_{k-1} (1+ g_{k-1} x_{k-1}) -\frac{\beta_k}{y_{k-1}} f_{k-2} = f_k y_k (1+g_k x_{k-1}+g_k x_k),
\end{align*}
and
\begin{align*}
    & \alpha_k f_{k-1}g_{k-1}-\frac{\beta_k}{y_{k-1}} f_{k-2} g_{k-2} = f_k g_k y_k.
\end{align*}
We therefore get
\begin{align*}
    & \alpha_k \det M_{k-1} -\beta_k \det M_{k-2} \\
    & = \left( f_k y_k(1+g_k x_{k-1}+g_k x_k)+ f_k g_k y_k \sum_{i=0}^{k-2} x_i\right) \prod_{i=0}^{k-1} y_i\\

    & = f_k \left( 1+g_k \sum_{i=0}^{k} x_i\right) \prod_{i=0}^{k} y_i\\
    & = \det M_k,
\end{align*}
and thus \eqref{E:mkdet} satisfies \eqref{E:mrecursion}. It is also possible to show that
\begin{align*}
    & \alpha_N f_{N-1}(1+ g_{N-1} x_{N-1}) -\frac{\beta_N}{y_{N-1}} f_{N-2} = \frac{(2N+1)^2}{(N+1)^2}, \\
    & \alpha_N f_{N-1} g_{N-1}-\frac{\beta_N}{y_{N-1}} f_{N-2} g_{N-2} = 0,
\end{align*}
thus, for $k=N$
\begin{align*}
    & \alpha_N \det M_{N-1} -\beta_N \det M_{N-2} \\
    & = \frac{(2N+1)^2}{(N+1)^2} \prod_{i=0}^{N-1} y_i  \\
    & = \det M_N,
\end{align*}
and the expression \eqref{E:mndet} is also verified.
